const cfToken = '${CLOUDFLARE_API_TOKEN}';
const cfZone = '${CLOUDFLARE_ZONE_ID}';
const baseUrl = `https://api.cloudflare.com/client/v4/zones/${cfZone}/dns_records`;
const headers = { 'Authorization': `Bearer ${cfToken}`, 'Content-Type': 'application/json' };

// Proper DoH endpoints (JSON format)
const dohEndpoints = [
  { name: 'Cloudflare', url: 'https://cloudflare-dns.com/dns-query' },
  { name: 'Google', url: 'https://dns.google/resolve' }
];

async function checkDomain(domain, endpoint) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${endpoint.url}?name=${domain}&type=A`,
      headers: { 'Accept': 'application/dns-json' },
      json: true,
      timeout: 8000
    });
    return { resolver: endpoint.name, ok: resp.Status === 0, answers: (resp.Answer||[]).map(a => a.data) };
  } catch(e) {
    return { resolver: endpoint.name, ok: false, error: e.message };
  }
}

// Get all public A records from Cloudflare
const resp = await this.helpers.httpRequest({ method: 'GET', url: `${baseUrl}?per_page=100&type=A`, headers, json: true });
const records = (resp.result || []).filter(r => !r.name.startsWith('edns-') && !r.name.includes('.int.'));

const issues = [];
for (const r of records) {
  const checks = await Promise.all(dohEndpoints.map(ep => checkDomain.call(this, r.name, ep)));
  const allOk = checks.every(c => c.ok);
  if (!allOk) {
    issues.push({ name: r.name, expected: r.content, proxied: r.proxied, failed: checks.filter(c => !c.ok).map(c => `${c.resolver}: ${c.error || 'NXDOMAIN'}`) });
  }
}

// If there are issues, report to the inbox
if (issues.length > 0) {
  const desc = issues.map(i => `- ${i.name} (proxied=${i.proxied}) failed: ${i.failed.join(', ')}`).join('\n');
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n.${BASE_DOMAIN}/webhook/inbox',
    headers: { 'Content-Type': 'application/json' },
    body: { type: 'bug', title: `DNS: ${issues.length} record(s) failing resolution`, description: `DNS Health Monitor alert:\n${desc}`, source: 'dns-health-monitor', priority: 'high' },
    json: true
  });
}

return [{ json: { timestamp: new Date().toISOString(), checked: records.length, healthy: records.length - issues.length, issues: issues.length, details: issues } }];
